import pyAether as pyScript

def use_dbfindinst(cv, inst_name, vector=False):
    name = pyScript.emyString(inst_name)
    return pyScript.dbFindInst(cv=cv, name=name, bVectorInst=vector)

import pyAether as pyScript

def vary_emyfiggetpinname(figs):
    return [pyScript.emyFigGetPinName(f) for f in figs]

import pyAether as pyScript

def vary_dbgetpinfigname(figs):
    out = []
    for f in figs:
        out.append(pyScript.dbGetPinFigName(fig=f))
    return out

import pyAether as pyScript

def find_inst_pin_name(lib, cell, inst_name):
    cv = pyScript.dbOpenCV(lib=lib, cell=cell, view="layout")
    name = pyScript.emyString(inst_name)
    figId = pyScript.dbFindInst(cv=cv, name=name)
    return pyScript.dbGetPinFigName(fig=figId)
